import { mapState } from "vuex";
import { integralCategory, integralCreate, integralCategoryEdit, categorySetShow } from "@/api/marketing";
export default {
  name: "user_group",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      columns1: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "分类名称",
          key: "name",
          minWidth: 100,
        },
        {
          title: "积分范围",
          slot: "range",
          minWidth: 100,
        },
        {
          title: "状态",
          slot: "status",
          minWidth: 100,
        },
        {
          title: "排序",
          key: "sort",
          minWidth: 100,
        },
        {
          title: "操作",
          slot: "action",
          width: 120,
        },
      ],
      sortFrom: {
        page: 1,
        limit: 15,
        name: "",
        is_show: '',
      },
      list: [],
      total: 0,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 85;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getList();
  },
  methods: {
    sortSearchs() {
      this.sortFrom.page = 1;
      this.list = [];
      this.getList();
    },
    // 修改状态
    onchangeIsShow (row) {
      let data = {
        id: row.id,
        is_show: row.is_show
      }
      categorySetShow(data).then(async res => {
        this.$Message.success(res.msg);
        this.getList()
      }).catch(res => {
        this.$Message.error(res.msg);
      })
    },
    // 添加
    add() {
      this.$modalForm(integralCreate()).then(() => this.getList());
    },
    // 分类列表
    getList() {
      this.loading = true;
      integralCategory(this.sortFrom)
          .then((res) => {
            let data = res.data;
            this.list = data.list;
            this.total = data.count;
            this.loading = false;
          })
          .catch((err) => {
            this.loading = false;
            this.$Message.error(err.msg);
          });
    },
    pageChange(index) {
      this.sortFrom.page = index;
      this.getList();
    },
    //修改
    edit(id) {
      this.$modalForm(integralCategoryEdit(id)).then(() => this.getList());
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/marketing/integral/category/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.list.splice(num, 1);
            if (!this.list.length) {
              this.sortFrom.page =
                  this.sortFrom.page == 1 ? 1 : this.sortFrom.page - 1;
            }
            this.getList();
          })
          .catch((err) => {
            this.$Message.error(err.msg);
          });
    },
  },
};
